/**
 * Meta Notes entry point.
 *
 * `virtual:iwsdk-project` is generated by the IWSDK Vite plugin from
 * iwsdk.config.json (scene, assets, components, XR features). It is passed to
 * World.create() unchanged; app systems are registered explicitly below.
 *
 * Start-up order matters: the NoteSession is provided to the world before the
 * systems that read it are registered.
 */

import { World } from '@iwsdk/core';
import projectOptions from 'virtual:iwsdk-project';
import { provideNoteSession } from './notes/note-services.js';
import { NoteSession } from './notes/note-session.js';
import { IndexedDbNoteStore, SimulatedFailureStore } from './notes/note-store.js';
import { CameraCaptureSystem } from './systems/camera-capture-system.js';
import { InkSystem } from './systems/ink-system.js';
import { NotesPanelSystem } from './systems/notes-panel-system.js';
import { TabletHandleSystem } from './systems/tablet-handle-system.js';
import { XrStatusSystem } from './systems/xr-status-system.js';
import { installDevHooks } from './util/dev-hooks.js';

// Notes live in IndexedDB. `?simulateSaveFailure` makes every write fail, to
// check that the app keeps unsaved work and reports the problem.
const store = new SimulatedFailureStore(new IndexedDbNoteStore());
store.failWrites = new URLSearchParams(location.search).has('simulateSaveFailure');
const session = new NoteSession(store);

World.create(
  document.getElementById('scene-container') as HTMLDivElement,
  projectOptions,
).then((world) => {
  provideNoteSession(world, session);
  world
    .registerSystem(TabletHandleSystem)
    .registerSystem(InkSystem)
    .registerSystem(NotesPanelSystem)
    .registerSystem(CameraCaptureSystem)
    .registerSystem(XrStatusSystem);

  session.attachLifecycle();
  void session.load();
  installDevHooks({ world, session, store });
});
